import{_ as l,a0 as o,w as d,s as r,ao as t,I as i,x as a,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"ZOMBIES：我的軟件開發和測試簡便指南（一） | LCTT x X-CMD","titleTemplate":false,"description":"ZOMBIES：我的軟件開發和測試簡便指南（一） | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"ZOMBIES：我的軟件開發和測試簡便指南（一） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"ZOMBIES：我的軟件開發和測試簡便指南（一） | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20210201 My handy guide to software development and testing","title":"ZOMBIES：我的軟件開發和測試簡便指南（一）","tag":"202305","desc":""},"relativePath":"202305/20210201 My handy guide to software development and testing.md","filePath":"[post].md"}'),g={name:"202305/20210201 My handy guide to software development and testing.md"};function c(h,s,u,k,b,f){const n=o("Link");return d(),r("div",null,[s[27]||(s[27]=t('<h1 id="zombies-我的軟件開發和測試簡便指南-一" tabindex="-1">ZOMBIES：我的軟件開發和測試簡便指南（一） <a class="header-anchor" href="#zombies-我的軟件開發和測試簡便指南-一" aria-label="Permalink to “ZOMBIES：我的軟件開發和測試簡便指南（一）”">​</a></h1><blockquote><p>編程過程有時候就像一場與喪屍羣之間的戰鬥。在這個系列文章中，我將帶你瞭解怎樣將 ZOMBIES 方法應用到實際工作中。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202305/13/135130gn78t5b5kippl5nu.jpg" alt=""></p><p>很久以前，在我還是一個萌新程序員的時候，我們曾經被分配一大批工作。我們每個人都被分配了一個編程任務，然後回到自己的小隔間裏噼裏啪啦地敲鍵盤。我記得團隊裏的成員在自己的小隔間裏一呆就是幾個小時，為打造無缺陷的程序而奮鬥。當時流行的思想是：能一次性做得越多，能力越強。</p><p>對於我來説，能夠長時間編寫或者修改代碼而不用中途停下來檢驗這些代碼是否有效，就像榮譽勳章一樣。那個時候我們都認為停下來檢驗代碼是否工作是能力不足的表現，菜鳥才這麼幹。一個“真正的開發者”應該能一口氣構建起整個程序，中途不用停下來檢查任何東西！</p><p>然而事與願違，當我停止在開發過程中測試自己的代碼之後，來自現實的檢驗狠狠地打了我的臉。我的代碼要麼無法通過編譯，要麼構建失敗，要麼無法運行，或者不能按預期處理數據。我不得不在絕望中掙扎着解決這些煩人的問題。</p><h3 id="避開喪屍羣" tabindex="-1">避開喪屍羣 <a class="header-anchor" href="#避開喪屍羣" aria-label="Permalink to “避開喪屍羣”">​</a></h3><p>如果你覺得舊的工作方式聽起來很混亂，那是因為它確實是這樣的。我們一次性處理所有的任務，在問題堆裏左砍右殺，結果只是引出更多的問題。着就像是跟一大羣喪屍間的戰鬥。</p>',8)),i("p",null,[s[1]||(s[1]=a("如今我們已經學會了避免一次性做太多的事情。在最初聽到一些專家推崇避免大批量地開發的好處時，我覺得這很反直覺，但我已經從過去的犯錯中吸取了教訓。我使用被 ",-1)),e(n,{href:"https://www.agilealliance.org/resources/speakers/james-grenning/"},{default:p(()=>[...s[0]||(s[0]=[a("James Grenning",-1)])]),_:1}),s[2]||(s[2]=a(" 稱為 ",-1)),s[3]||(s[3]=i("strong",null,"ZOMBIES",-1)),s[4]||(s[4]=a(" 的方法來指導我的軟件開發工作。",-1))]),s[28]||(s[28]=t('<h3 id="zombies-方法來救援" tabindex="-1">ZOMBIES 方法來救援! <a class="header-anchor" href="#zombies-方法來救援" aria-label="Permalink to “ZOMBIES 方法來救援!”">​</a></h3><p>ZOMBIES 表示以下首字母縮寫：</p><ul><li><strong>Z</strong> – 最簡場景（Zero）</li><li><strong>O</strong> – 單元素場景（One）</li><li><strong>M</strong> – 多元素場景（Many or more complex）</li><li><strong>B</strong> – 邊界行為（Boundary behaviors）</li><li><strong>I</strong> – 接口定義（Interface definition）</li><li><strong>E</strong> – 處理特殊行為（Exercise exceptional behavior）</li><li><strong>S</strong> – 簡單場景用簡單的解決方案（Simple scenarios, simple solutions）</li></ul><p>我將在本系列文章中對它們進行分析講解。</p><h3 id="最簡場景" tabindex="-1">最簡場景 <a class="header-anchor" href="#最簡場景" aria-label="Permalink to “最簡場景”">​</a></h3><p>最簡場景指可能出現的最簡單的情況。</p><p>人們傾向於最開始的時候使用硬編碼值，因為這是最簡單的方式。通過在編碼活動中使用硬編碼值，可以快速構建出一個能即時反饋的解決方案。不需要幾分鐘，更不用幾個小時，使用硬編碼值讓你能夠馬上與正在構建的系統進行交互。如果你喜歡這個交互，就朝這個方向繼續做下去。如果你發現不喜歡這種交互，你可以很容易拋棄它，根本沒有什麼可損失。</p><p>本系列文章將以構建一個簡易的購物系統的後端 API 為例進行介紹。該服務提供的 API 允許用户創建購物筐、向購物筐添加商品、從購物筐移除商品、計算商品總價。</p>',8)),i("p",null,[s[6]||(s[6]=a("首先，創建項目的基本結構（將購物程序的代碼和測試代碼分別放到 ",-1)),s[7]||(s[7]=i("code",null,"app",-1)),s[8]||(s[8]=a(" 和 ",-1)),s[9]||(s[9]=i("code",null,"tests",-1)),s[10]||(s[10]=a(" 目錄下）。我們的例子中使用開源的 ",-1)),e(n,{href:"https://xunit.net/"},{default:p(()=>[...s[5]||(s[5]=[a("xUnit",-1)])]),_:1}),s[11]||(s[11]=a(" 測試框架。",-1))]),s[29]||(s[29]=t(`<p>現在擼起你的袖子，在實踐中瞭解最簡場景吧！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Fact]</span></span>
<span class="line"><span>public void NewlyCreatedBasketHas0Items() {    </span></span>
<span class="line"><span>    var expectedNoOfItems = 0;</span></span>
<span class="line"><span>    var actualNoOfItems = 1;</span></span>
<span class="line"><span>    Assert.Equal(expectedNoOfItems, actualNoOfItems);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>這是一個偽測試，它測試的是硬編碼值。新創建的購物筐是空的，所以購物筐中預期的商品數是 0。通過比較期望值和實際值是否相等，這個預期被表示成一個測試（或者稱為斷言）。</p><p>運行該測試，輸出結果如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Starting test execution, please wait...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>A total of 1 test files matched the specified pattern.</span></span>
<span class="line"><span>[xUnit.net 00:00:00.57] tests.UnitTest1.NewlyCreatedBasketHas0Items [FAIL]</span></span>
<span class="line"><span>  X tests.UnitTest1.NewlyCreatedBasketHas0Items [4ms]</span></span>
<span class="line"><span>  Error Message:</span></span>
<span class="line"><span>   Assert.Equal() Failure</span></span>
<span class="line"><span>Expected: 0</span></span>
<span class="line"><span>Actual: 1</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>這個測試顯然無法通過：期望商品數是 0，但是實際值被硬編碼為了 1。</p><p>當然，你可以馬上把硬編碼的值從 1 改成 0，這樣測試就能通過了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Fact]</span></span>
<span class="line"><span>public void NewlyCreatedBasketHas0Items() {</span></span>
<span class="line"><span>    var expectedNoOfItems = 0;</span></span>
<span class="line"><span>    var actualNoOfItems = 0;</span></span>
<span class="line"><span>    Assert.Equal(expectedNoOfItems, actualNoOfItems);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>與預想的一樣，運行測試，測試通過：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Starting test execution, please wait...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>A total of 1 test files matched the specified pattern.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Test Run Successful.</span></span>
<span class="line"><span>Total tests: 1</span></span>
<span class="line"><span>     Passed: 1</span></span>
<span class="line"><span> Total time: 1.0950 Seconds</span></span></code></pre></div><p>你也許會認為執行一個被強迫失敗的測試完全沒有意義，但是不管一個測試多麼簡單，確保它的可失敗性是絕對有必要的。只有這樣才能夠保證如果在後續工作中不小心破壞了程序的處理邏輯時該測試能夠給你相應的警告。</p><p>現在停止偽造數據，將硬編碼的值替換成從 API 中獲取的值。我們已經構造了一個能夠可靠地失敗的測試，它期望一個空的購物筐中有 0 個商品，現在是時候編寫一些應用程序代碼了。</p><p>就跟常見的軟件建模活動一樣，我們先從構造一個簡單的接口開始。在 <code>app</code> 目錄下新建文件 <code>IShoppingAPI.cs</code>（習慣上接口名一般以大寫 I 開頭）。在該接口中聲明一個名為 <code>NoOfItems()</code> 的方法，它以 <code>int</code> 類型返回商品的數量。下面是接口的代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>using System;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>namespace app {    </span></span>
<span class="line"><span>    public interface IShoppingAPI {</span></span>
<span class="line"><span>        int NoOfItems();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>當然這個接口什麼事也做不了，在你需要實現它。在 <code>app</code> 目錄下創建另一個文件 <code>ShoppingAPI</code>。在其中將 <code>ShoppingAPI</code> 聲明為一個實現了 <code>IShoppingAPI</code> 的公有類。在類中定義方法 <code>NoOfItems</code> 返回整數 1：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>using System;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>namespace app {</span></span>
<span class="line"><span>    public class ShoppingAPI : IShoppingAPI {</span></span>
<span class="line"><span>        public int NoOfItems() {</span></span>
<span class="line"><span>            return 1;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>從上面代碼中你發現自己又在通過返回硬編碼值 1 的方式來偽造代碼邏輯。現階段這是一件好事，因為你需要保持一切超級無敵簡單。現在還不是仔細構想如何實現購物筐的處理邏輯時候。這些工作後續再做！到目前為止，你只是通過構建最簡場景來檢驗自己是否滿意現在的設計。</p><p>為了確定這一點，將硬編碼值換成這個 API 在運行中收到請求時應該返回的值。你需要通過 <code>using app;</code> 聲明來告訴測試你使用的購物邏輯代碼在哪裏。</p><p>接下來，你需要 <ruby>實例化<rt>instantiate</rt></ruby> <code>IShoppingAPI</code> 接口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>IShoppingAPI shoppingAPI = new ShoppingAPI();</span></span></code></pre></div><p>這個實例用來發送請求並接收返回的值。</p><p>現在，代碼變成了這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>using System;</span></span>
<span class="line"><span>using Xunit;</span></span>
<span class="line"><span>using app;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>namespace tests {</span></span>
<span class="line"><span>    public class ShoppingAPITests {</span></span>
<span class="line"><span>        IShoppingAPI shoppingAPI = [new][3] ShoppingAPI();</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>        [Fact]        </span></span>
<span class="line"><span>        public void NewlyCreatedBasketHas0Items() {</span></span>
<span class="line"><span>            var expectedNoOfItems = 0;</span></span>
<span class="line"><span>            var actualNoOfItems = shoppingAPI.NoOfItems();</span></span>
<span class="line"><span>            Assert.Equal(expectedNoOfItems, actualNoOfItems);</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>顯然執行這個測試的結果是失敗，因為你硬編碼了一個錯誤的返回值（期望值是 0，但是返回的是 1）。</p><p>同樣的，你也可以通過將硬編碼的值從 1 改成 0 來讓測試通過，但是現在做這個是在浪費時間。現在設計的接口已經跟測試關聯上了，你剩下的職責就是編寫代碼實現預期的行為邏輯。</p><p>在編寫應用程序代碼時，你得決定用來表示購物筐得數據結構。為了保持設計的簡單，儘量選擇 C# 中表示集合的最簡單類型。第一個想到的就是 <code>ArrayList</code>。它非常適合目前的使用場景——可以保存不定個數的元素，並且易於遍歷訪問。</p><p>因為 <code>ArrayList</code> 是 <code>System.Collections</code> 包的一部分，在你的代碼中需要聲明：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>using System.Collections;</span></span></code></pre></div><p>然後 <code>basket</code> 的聲明就變成這樣了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ArrayList basket = new ArrayList();</span></span></code></pre></div><p>最後將 <code>NoOfItems()</code> 中的因編碼值換成實際的代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>public int NoOfItems() {</span></span>
<span class="line"><span>    return basket.Count;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>這次測試能夠通過了，因為最初購物筐是空的，<code>basket.Count</code> 返回 0。</p><p>這也是你的第一個最簡場景測試要做的事情。</p><h3 id="更多案例" tabindex="-1">更多案例 <a class="header-anchor" href="#更多案例" aria-label="Permalink to “更多案例”">​</a></h3><p>目前的課後作業是處理一個喪屍，也就是第 0 個喪屍。在下一篇文章中，我將帶你瞭解單元素場景和多元素場景。不要錯過哦！</p><p><em>（題圖：MJ/7917bc47-5325-4c0f-a2dd-4e444f57a46c）</em></p><hr>`,38)),i("p",null,[s[13]||(s[13]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/21/2/development-guide"},{default:p(()=>[...s[12]||(s[12]=[a("https://opensource.com/article/21/2/development-guide",-1)])]),_:1})]),i("p",null,[s[18]||(s[18]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/alex-bunardzic"},{default:p(()=>[...s[14]||(s[14]=[a("Alex Bunardzic",-1)])]),_:1}),s[19]||(s[19]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[15]||(s[15]=[a("lujun9972",-1)])]),_:1}),s[20]||(s[20]=a(" 譯者：",-1)),e(n,{href:"https://github.com/toknow-gh"},{default:p(()=>[...s[16]||(s[16]=[a("toknow-gh",-1)])]),_:1}),s[21]||(s[21]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[17]||(s[17]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[24]||(s[24]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[22]||(s[22]=[a("LCTT",-1)])]),_:1}),s[25]||(s[25]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[23]||(s[23]=[a("Linux中國",-1)])]),_:1}),s[26]||(s[26]=a(" 榮譽推出",-1))])])}const C=l(g,[["render",c]]);export{y as __pageData,C as default};
